// @ts-ignore: generated by the build step
import { createApp } from '../dist-server/server.js';
let appPromise: Promise<any> | null = null;
export default async function handler(req: any, res: any) {
  const route = String(req.query?.route || 'status');
  if (!/^[a-z\-/]+$/.test(route)) { res.status(400).json({error:'Invalid notification route.'}); return; }
  req.url = '/api/notifications/' + route;
  if (!appPromise) appPromise = createApp();
  return (await appPromise)(req, res);
}
